#pragma once

// Minimal JSON extraction helpers for the status caches written by
// rockbase_statusd.sh and the stratum service. Pure standard C++ (no LVGL)
// so this layer can be built and unit-tested on the host.
//
// DESIGN NOTE — why a scanner and not a real parser (decision, 2026-09-30):
// These are intentionally small token-scan helpers, NOT a JSON parser. The
// caches are machine-generated by shell scripts in this repo (a controlled
// contract, flat/stable schema) and are written atomically (tmp + rename),
// so a full DOM parse buys little. The scan helpers re-read ~125KB every
// 5s with near-zero heap allocation on a RAM-tight, weeks-long-uptime
// K230, and degrade per-field to a fallback ("-" ) instead of failing the
// whole page if a field is malformed. Replacing with a real parser (cJSON
// is already in the image via webrtc) was evaluated and DEFERRED: the
// gain (robustness to schema drift / key collisions) is moderate against
// the cost (per-refresh DOM heap, all-or-nothing parse failure).
// The quirks these helpers exhibit are pinned by core/test/test_core.cpp;
// if the decision is revisited, keep the public signatures stable and
// re-verify against those fixtures.

#include <cstddef>
#include <string>
#include <vector>

namespace lcdui {

size_t skip_ws(const std::string& s, size_t pos);
std::string json_unescape(const std::string& value);
std::string json_object(const std::string& json, const char* object_name);
std::string json_array(const std::string& json, const char* array_name);
std::string json_value(const std::string& object, const char* key, const char* fallback = "-");
std::vector<std::string> json_string_array(const std::string& array_json);
std::vector<std::string> json_array_objects(const std::string& array_json);
double json_double(const std::string& object, const char* key, double fallback);
int json_int_value(const std::string& object, const char* key, int fallback = 0);
int parse_int_or(const std::string& text, int fallback);
long parse_leading_int(const std::string& value, long fallback = -1);

}  // namespace lcdui
